/* Обычный класс — задаётся в HTML */
.active { color: red; }

/* Псевдокласс — состояние определяется браузером */
a:hover { color: red; }

/* Обычный фокус */
input:focus {
  border-color: blue;
}

/* Фокус только от клавиатуры */
button:focus-visible {
  outline: 2px solid blue;
  outline-offset: 2px;
}

/* Подсветка секции при переходе по якорю */
:target {
  background: #fffde7;
  border-left: 4px solid gold;
}

/* Выбранный чекбокс/радио */
input:checked { accent-color: blue; }

/* Заблокированные поля */
input:disabled {
  background: #f5f5f5;
  cursor: not-allowed;
}

/* Обязательное поле */
input:required { border-left: 3px solid orange; }

/* Поле с валидным значением */
input:valid { border-color: green; }

/* Поле с невалидным значением */
input:invalid { border-color: red; }

/* Пустое поле с placeholder */
input:placeholder-shown { color: #999; }

/* Первый элемент */
li:first-child { font-weight: bold; }

/* Последний элемент */
li:last-child { border-bottom: none; }

/* Нечётные элементы */
tr:nth-child(odd) { background: #f5f5f5; }

/* Чётные элементы */
tr:nth-child(even) { background: white; }

/* Каждый 3-й элемент */
li:nth-child(3n) { color: red; }

/* Первый из своего типа */
p:first-of-type { font-size: 1.2em; }

/* Выберет ТРЕТИЙ элемент среди всех соседей (span) */
:nth-child(3) { color: red; }

/* Выберет ВТОРОЙ <p> среди <p> */
:nth-of-type(2) { color: blue; }
